import{_ as t,c as r,o as l,ah as o}from"./chunks/framework.PvdZnrZd.js";const u=JSON.parse('{"title":"Seller Guide","description":"Seller Guide","frontmatter":{"title":"Seller Guide","description":"Seller Guide","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/seller/seller-guide.md","filePath":"zenith/seller/seller-guide.md"}'),a={name:"zenith/seller/seller-guide.md"};function n(s,e,i,p,d,c){return l(),r("div",null,[...e[0]||(e[0]=[o('<p>Let&#39;s have a look at the Seller Guide for this app.</p><p>In the app, the sellers/vendors need to either create an account on the store on their own or the admin/store owner can add them and create their account.</p><p>This is a basic Seller guide for the Sellers on your Marketplace.</p><p>There are certain steps that the seller needs to follow :</p><ol><li>Sign up/Login to the Seller Account.</li><li>If the Seller has signup then wait for account approval from the Admin.</li><li>Once approved, the seller can start uploading the products.</li><li>Products also need to be approved by the Admin.</li><li>Once approved, the products will be available on the Shopify Store.</li><li>The seller needs to add the payment details to which he wish to receive the order payments.</li><li>The seller can contact the Admin in case of an issue.</li></ol><h2 id="seller-login-sign-up" tabindex="-1">Seller Login/Sign up: <a class="header-anchor" href="#seller-login-sign-up" aria-label="Permalink to &quot;Seller Login/Sign up:&quot;">​</a></h2><p><strong>Note</strong>: <a href="/zenith/configuration/configuration-updates.html#google-recaptcha-configuration">Google Recaptcha</a> will be mandatory for Seller Signup after <strong>24th September 2022.</strong></p><p>The seller/vendor needs to sign up on the store or log in to access the account.</p><p>The seller will be provided a URL from the admin, which you can use to signup/login. Or sellers can do it from the link on the admin Shopify store.</p><p>This the signup/login page for the seller.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellersignup.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellersignup.webp" alt="Seller Guide"></a></p><p>To start adding products to the store, the seller needs to register/log in.</p><p><strong>Please note:</strong> Each IP address is allowed a <strong>maximum of 20 signup requests per hour</strong>.</p><p>If more than 20 requests are made from the same IP within the same time frame, <strong>new seller accounts cannot be created</strong> during that period.</p><h2 id="seller-dashboard" tabindex="-1">Seller dashboard <a class="header-anchor" href="#seller-dashboard" aria-label="Permalink to &quot;Seller dashboard&quot;">​</a></h2><p>This is the view of the seller dashboard once the seller has successfully logged in.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerdasboard.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerdasboard.webp" alt="Seller Guide Dashboard"></a></p><p>The seller can have an idea of the products, orders, commission (admin share in the order), etc by just looking at the dashboard.</p><h2 id="configuration" tabindex="-1">configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;configuration&quot;">​</a></h2><p>The Seller can manage the invoice and all the other configuration (if enabled from the admin).</p><p>Here is the screenshot of the invoice configuration that will be sent from the seller to the customer.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerconfiguration.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerconfiguration.webp" alt="Seller Guide Invoice"></a></p><p>This way seller can manage the invoice.</p><h2 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h2><p>Under this menu- products &gt;&gt; product listing, all the product-related information will be there and the product can be edited, viewed and deleted from here :</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerproductlisting.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerproductlisting.webp" alt="Seller Products"></a></p><p>Further, from the &quot;bulk edit&quot; option in the above screenshot, the seller can bulk edit the products and can add the products via CSV file to the app</p><p>This is the &quot;add product&quot; form :</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/selleraddproduct-scaled.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/selleraddproduct-scaled.webp" alt="Add Products"></a></p><p>This way you can add the product.</p><p>In case you have selected &quot;digital product&quot; to be added then the form will differ as you have to upload the file and also specify the number of allowed downloads and the expiry days (if any)</p><p>This is how you add a new product.</p><p>We have another menu here: Products &gt; Smart Collections: A list of all the automated/smart collections made at Shopify end.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellersmartcollection.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellersmartcollection.webp" alt="Smart Collection • Multivendor MarketPlace"></a></p><h2 id="orders" tabindex="-1">orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;orders&quot;">​</a></h2><p>A seller can view and can manage all the order from the &quot;orders&quot; menu under order listing :</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerorderlisting.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerorderlisting.webp" alt="track order"></a></p><p>The order listing page will list all the orders placed for the seller and the seller can fulfill the order by viewing the order from the order view page.</p><p>Moreover, from the order view, the seller can enter the tracking number for the order and can also print the invoice for that particular order.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/seller-add-tracking-no-7.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/seller-add-tracking-no-7.png" alt="edit tracking"></a></p><p>Under the order menu, the submenu &quot;payment received&quot;, this section shows the payment due and the total payment received by the seller.</p><p>Orders &gt; Payment Received: A list of all the payments received by the seller with payment status:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerorderpayment.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerorderpayment.webp" alt="Payment Receive Seller • Multivendor MarketPlace"></a></p><p>Orders &gt; Commission Listing: A list of all the admin commissions on his orders:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellercommission.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellercommission.webp" alt="Commissions Seller • Multivendor MarketPlace"></a></p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>Sellers can manage their accounts from the &quot;My Account&quot; submenu under the Profile menu.</p><p>With the &quot;My Account&quot; page, sellers can manage their profile picture, banner image, and all personal information:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellermyaccount-scaled.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellermyaccount-scaled.webp" alt="seller my account"></a></p><p>Under the &quot;Payment Details&quot; submenu, a seller can add the details of the payment mode by which he wishes to receive his earning from the store owner:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerpaymentdetails.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerpaymentdetails.webp" alt="payment detail"></a></p><p>The feedback submenu will show all the feedback received by the seller from the customer from the seller profile page.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerfeedback.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/sellerfeedback.webp" alt="Feedback Seller • Multivendor MarketPlace"></a></p><h3 id="multivendor-marketplace-seller-guide-demo" tabindex="-1">Multivendor Marketplace: Seller Guide Demo <a class="header-anchor" href="#multivendor-marketplace-seller-guide-demo" aria-label="Permalink to &quot;Multivendor Marketplace: Seller Guide Demo&quot;">​</a></h3><p>Further, check out: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p>',55)])])}const b=t(a,[["render",n]]);export{u as __pageData,b as default};
